package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.sacramento.TipoSacramento; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/sacramentos") public class RelatorioSacramentoWebController { private final RelatorioSacramentoApplicationService service; private final RelatorioContextoService contexto; public RelatorioSacramentoWebController(RelatorioSacramentoApplicationService s,RelatorioContextoService c){service=s;contexto=c;}
 @GetMapping public String consultar(@RequestParam(defaultValue="registros") String visao,@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) TipoSacramento tipo,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataFim,@RequestParam(required=false) String pessoa,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){if(!"pessoas".equals(visao))visao="registros";m.addAttribute("visao",visao);m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("tipo",tipo);m.addAttribute("tipos",TipoSacramento.values());m.addAttribute("dataInicio",dataInicio);m.addAttribute("dataFim",dataFim);m.addAttribute("pessoa",pessoa);if(organizacaoUuid!=null){var f=new RelatorioSacramentoFiltro(organizacaoUuid,tipo,dataInicio,dataFim,pessoa,pagina,tamanho);m.addAttribute("resultado","pessoas".equals(visao)?service.pessoas(f):service.registros(f));}return "relatorio/sacramentos";}
}
